contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address adr, bytes memory data, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeBal = address(c).balance;
        bool reverted;
        c.Command{value: amount}(adr, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = address(c).balance;

        assert(reverted || afterBal + amount >= beforeBal);
    }

    receive() external payable {}

    fallback() external payable {}
}

